-- Video checkpoints ("استنى وحل السؤال ده الأول"): LectureCheckpoints, LectureCheckpointQuestions,
-- LectureCheckpointProgresses, LectureCheckpointAttempts.
--
-- NOT required to run by hand: the migration 20261108120000_AddLectureCheckpoints applies the
-- same idempotent statements automatically on server start. Safe to run more than once. (PostgreSQL)

CREATE TABLE IF NOT EXISTS "LectureCheckpoints" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "LectureId" integer NOT NULL,
  "Seconds" integer NOT NULL,
  "Title" character varying(120) NULL,
  "MaxAttempts" integer NOT NULL DEFAULT 3,
  "IsActive" boolean NOT NULL DEFAULT true,
  "CreatedAt" timestamp with time zone NOT NULL,
  "UpdatedAt" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_LectureCheckpoints_LectureId_Seconds" ON "LectureCheckpoints" ("LectureId","Seconds");

CREATE TABLE IF NOT EXISTS "LectureCheckpointQuestions" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "CheckpointId" integer NOT NULL,
  "BankQuestionId" integer NOT NULL,
  "SortOrder" integer NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS "IX_LectureCheckpointQuestions_CheckpointId" ON "LectureCheckpointQuestions" ("CheckpointId");

CREATE TABLE IF NOT EXISTS "LectureCheckpointProgresses" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "CheckpointId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "Passed" boolean NOT NULL DEFAULT false,
  "PassedFirstTry" boolean NOT NULL DEFAULT false,
  "PassedAt" timestamp with time zone NULL,
  "WrongInRound" integer NOT NULL DEFAULT 0,
  "AskedCsv" text NOT NULL DEFAULT '',
  "CurrentQuestionId" integer NULL,
  "TotalAttempts" integer NOT NULL DEFAULT 0,
  "TotalWrong" integer NOT NULL DEFAULT 0,
  "UpdatedAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_LectureCheckpointProgresses_CheckpointId_StudentId" ON "LectureCheckpointProgresses" ("CheckpointId","StudentId");

CREATE TABLE IF NOT EXISTS "LectureCheckpointAttempts" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "CheckpointId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "BankQuestionId" integer NOT NULL,
  "Answer" character varying(500) NULL,
  "IsCorrect" boolean NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_LectureCheckpointAttempts_CheckpointId_StudentId" ON "LectureCheckpointAttempts" ("CheckpointId","StudentId");
